function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.floor(x),Math.floor(y),Math.ceil(w),Math.ceil(h))}
function tileDraw(type,sx,sy,tx,ty){const seed=(tx*92821+ty*68917)%997; if(type===0){const greens=['#67935a','#70995d','#638b54','#759b60'];rect(sx,sy,16,16,greens[Math.abs(seed)%4]);if(seed%7===0){rect(sx+3,sy+4,2,2,'#8eac68');rect(sx+11,sy+10,1,1,'#426d4b')}if(seed%19===1){rect(sx+5,sy+9,2,2,'#e9c579');rect(sx+8,sy+8,2,2,'#fff0bd')}}else if(type===1){rect(sx,sy,16,16,state.area==='dungeon'?'#343b3c':'#52764b');rect(sx,sy,16,2,state.area==='dungeon'?'#495251':'#72905b');rect(sx+2,sy+5,3,2,'#3b5f43')}else if(type===2){rect(sx,sy,16,16,'#685b4c');rect(sx+1,sy+1,14,14,'#786955');if(seed%3===0)rect(sx+4,sy+5,2,1,'#9b856a');if(seed%5===0)rect(sx+11,sy+12,2,2,'#554c45')}else if(type===3){rect(sx,sy,16,16,'#b29770');rect(sx+1,sy+1,14,14,'#c7ad7b');rect(sx,sy+7,16,1,'#aa8d64');if(tx%2===0)rect(sx+7,sy,1,7,'#aa8d64');else rect(sx+2,sy+8,1,7,'#aa8d64')}else if(type===4){rect(sx,sy,16,16,'#497d83');rect(sx,sy+2,16,2,'#70a6a0');rect(sx+4,sy+9,5,1,'#96c4b5')}else if(type===5){rect(sx,sy,16,16,'#71634f');rect(sx+2,sy+2,12,12,'#b1935e');rect(sx+4,sy+4,8,8,'#d7bc7b');rect(sx+7,sy+7,2,2,'#eee0a1')}}
function drawVillageBuildings(){const b=(x,y,w,h,roof,name)=>{const X=x-camera.x,Y=y-camera.y;rect(X+2,Y+h-2,w,h*0.18,'#3e453c');rect(X,Y+8,w,h-8,'#d2b37b');rect(X+3,Y+11,w-6,h-15,'#c5a270');rect(X-3,Y,w+6,13,roof);rect(X+2,Y+2,w-4,2,roof==='#9b5548'?'#c06d52':'#b8784e');for(let i=8;i<w-3;i+=10)rect(X+i,Y+4,2,5,'#352f32');rect(X+w/2-5,Y+h-14,10,14,'#624337');rect(X+w/2-1,Y+h-9,2,2,'#e0bb70');ctx.fillStyle='#f0ddb3';ctx.font='5px monospace';ctx.textAlign='center';ctx.fillText(name,X+w/2,Y+h+6)};
 b(73,65,58,43,'#a94e46','DEMİRCİ');b(285,57,58,43,'#875447','HAN');b(314,141,56,42,'#ba7548','PAZAR');
 // fence and gardens
 for(let x=45;x<115;x+=9){rect(x-camera.x,124-camera.y,2,9,'#87694a');rect(x-camera.x,128-camera.y,4,2,'#a98a5e')}
 for(let x=145;x<166;x+=7)rect(x-camera.x,214-camera.y,3,4,'#e4b85c');
 // large trees
 for(const [x,y] of [[52,72],[161,51],[385,75],[385,116],[67,214],[378,245],[166,245],[272,222],[401,83],[40,165],[264,95]])drawTree(x-camera.x,y-camera.y);
 // village well
 rect(229-camera.x,222-camera.y,25,11,'#817a66');rect(232-camera.x,218-camera.y,19,10,'#a99a78');rect(235-camera.x,220-camera.y,13,6,'#426f76');rect(227-camera.x,217-camera.y,29,3,'#604b39');
}
function drawTree(x,y){rect(x-5,y+5,11,10,'#70513b');rect(x-10,y-4,20,13,'#416c48');rect(x-7,y-10,15,12,'#4e7c4c');rect(x-4,y-13,8,6,'#5d8951');rect(x-6,y-5,4,3,'#81a75e');rect(x+3,y+1,3,2,'#719653')}
function drawDungeonDetails(){// stone pillars, altar and torchlight
 for(const [x,y] of [[60,61],[176,61],[60,268],[176,268],[253,61],[365,61],[253,268],[365,268]]){const X=x-camera.x,Y=y-camera.y;rect(X-3,Y-3,7,9,'#515a55');rect(X-5,Y+4,11,3,'#747363');rect(X-1,Y-1,2,4,'#c4814a')}
 let X=209-camera.x,Y=108-camera.y;rect(X-11,Y+5,22,10,'#75664d');rect(X-8,Y,16,8,'#9a8155');rect(X-4,Y-5,8,7,'#63b5bd');rect(X-1,Y-3,2,3,'#b2f3dd');
 for(const [x,y] of [[80,80],[201,80],[355,80],[285,198]]){let a=Math.sin(Date.now()/140+x)*1;rect(x-camera.x,Y*0+a+y-camera.y,2,4,'#d18043');rect(x-1-camera.x,y-3-camera.y,4,2,'#e7b658')}
}
function drawHumanoid(x,y,color,dir,frame,isPlayer=false){x=Math.floor(x-camera.x);y=Math.floor(y-camera.y);const bob=frame%2?1:0; // feet
 rect(x-5,y+4+bob,4,3,'#4b3b35');rect(x+1,y+4+bob,4,3,'#4b3b35');rect(x-5,y-3+bob,10,8,color);rect(x-7,y-2+bob,3,6,'#d3a875');rect(x+4,y-2+bob,3,6,'#d3a875');rect(x-4,y-9+bob,8,7,'#e1b585');rect(x-5,y-10+bob,10,4,isPlayer?'#d7b75d':'#76574a');
 if(dir==='down'){rect(x-3,y-6+bob,2,2,'#302d32');rect(x+2,y-6+bob,2,2,'#302d32')}else if(dir==='left')rect(x-4,y-6+bob,2,2,'#302d32');else if(dir==='right')rect(x+2,y-6+bob,2,2,'#302d32');else{rect(x-4,y-10+bob,8,2,isPlayer?'#d7b75d':'#76574a')}
 if(isPlayer){rect(x-2,y-1+bob,4,5,'#4a8f89');rect(x-1,y-9+bob,3,2,'#9b5b4b');if(player.attackAnim>0){const a=player.dir==='left'?[x-12,y-5,8,2]:player.dir==='right'?[x+5,y-5,8,2]:player.dir==='up'?[x-4,y-15,2,8]:[x+4,y+1,2,8];rect(...a,'#fff0b0');rect(a[0]+2,a[1]+1,3,1,'#dce8df')}}}
function drawEntity(e){const x=Math.floor(e.x-camera.x),y=Math.floor(e.y-camera.y),pulse=Math.sin(Date.now()/180+e.x)*1; if(x<-30||x>W+30||y<-35||y>H+35)return;
 if(e.type==='mira'||e.type==='smith'||e.type==='merchant'||e.type==='innkeeper'||e.type==='villager'){const col={mira:'#b87963',smith:'#875a47',merchant:'#d3a254',innkeeper:'#729278',villager:'#8292a0'}[e.type];drawHumanoid(e.x,e.y,col,e.dir,Math.floor(Date.now()/200),false);rect(x-4,y-11,8,2,e.type==='mira'?'#dfd094':'#583e37')}
 else if(e.type==='wolf'){rect(x-7,y-2,14,7,'#8a6152');rect(x+3,y-7,7,7,'#a87a60');rect(x+4,y-10,2,4,'#715246');rect(x+9,y-9,2,4,'#715246');rect(x+8,y-5,2,2,'#f0ce72');rect(x-5,y+4,3,4,'#493b37');rect(x+3,y+4,3,4,'#493b37')}
 else if(e.type==='slime'){rect(x-7,y-1+pulse,14,8,'#78b877');rect(x-5,y-5+pulse,10,5,'#89cd7f');rect(x-3,y+1+pulse,2,2,'#293d37');rect(x+3,y+1+pulse,2,2,'#293d37')}
 else if(e.type==='wisp'){rect(x-4,y-5+pulse,8,9,'#b37ad0');rect(x-2,y-8+pulse,4,3,'#dbade7');rect(x-2,y-1+pulse,2,2,'#fff0a8');rect(x+2,y-1+pulse,2,2,'#fff0a8')}
 else if(e.type==='boss'){rect(x-12,y-4,24,17,'#44394f');rect(x-10,y-10,20,11,'#66536e');rect(x-8,y-16,6,9,'#826487');rect(x+2,y-16,6,9,'#826487');rect(x-7,y-6,4,3,'#ffd477');rect(x+3,y-6,4,3,'#ffd477');rect(x-8,y+12,5,4,'#2d2936');rect(x+4,y+12,5,4,'#2d2936');rect(x-2,y-10,4,11,'#67d6ca');if(e.hp<e.maxHp){rect(x-14,y-24,28,3,'#333');rect(x-14,y-24,28*e.hp/e.maxHp,3,'#c66a68')}}
 else if(e.type==='portal'){rect(x-11,y-8,4,19,'#7b6950');rect(x+7,y-8,4,19,'#7b6950');rect(x-12,y-11,24,4,'#ab9262');rect(x-7,y-3,14,12,'#35847f');rect(x-4,y-1,8,8,'#80c9a8');}
 else if(e.type==='chest'){rect(x-7,y-5,14,10,e.opened?'#705a39':'#9b693b');rect(x-7,y-5,14,3,'#dbb661');rect(x-1,y-2,2,4,'#f0da87')}
 else if(e.type==='block'){rect(x-8,y-8,16,16,'#776a58');rect(x-6,y-6,12,12,'#a58a61');rect(x-3,y-3,6,6,'#79644e')}
 else if(e.type==='save'){rect(x-5,y-7,10,14,'#61bfba');rect(x-3,y-5,6,10,'#b9ead1')}
}
function draw(){const area=maps[state.area];camera.x=clamp(player.x-W/2,0,area.w*T-W);camera.y=clamp(player.y-H/2,0,area.h*T-H);ctx.clearRect(0,0,W,H);
 const startX=Math.floor(camera.x/T),startY=Math.floor(camera.y/T),endX=Math.ceil((camera.x+W)/T),endY=Math.ceil((camera.y+H)/T);
 for(let ty=startY;ty<endY;ty++)for(let tx=startX;tx<endX;tx++){if(worldMap[ty]?.[tx]!==undefined)tileDraw(worldMap[ty][tx],tx*T-camera.x,ty*T-camera.y,tx,ty)}
 if(state.area==='village')drawVillageBuildings();else drawDungeonDetails();
 // dungeon trap warning pulse
 if(state.area==='dungeon'&&!state.plate){const sx=8*T-camera.x,sy=11*T-camera.y;rect(sx+3,sy+3,10,10,Math.sin(Date.now()/180)>0?'#b66a55':'#8c574e');rect(sx+6,sy+6,4,4,'#e5ad68')}
 entities.filter(e=>e.alive).sort((a,b)=>a.y-b.y).forEach(drawEntity);
 // player shadow and sprite
 ctx.fillStyle='#29352b77';ctx.fillRect(player.x-camera.x-6,player.y-camera.y+5,13,4);drawHumanoid(player.x,player.y,player.hit?'#e98471':'#548e85',player.dir,player.frame,true);
 for(const p of projectiles){rect(p.x-camera.x-2,p.y-camera.y-2,5,5,'#f4a959');rect(p.x-camera.x-1,p.y-camera.y-1,3,3,'#fff2a1')}
 for(const p of particles){if(p.type==='hit'){rect(p.x-camera.x+rand(-2,2),p.y-camera.y,2,2,'#fff0be')}else if(p.type==='spark'||p.type==='magic'){rect(p.x-camera.x+rand(-4,4),p.y-camera.y+rand(-5,5),2,2,p.type==='magic'?'#ffbf68':'#ffe594')}else{rect(p.x-camera.x,p.y-camera.y,2,2,'#c8bd8c')}}
 // ambient golden light overlay for evening
 const night=state.time<6||state.time>19;ctx.fillStyle=night?'rgba(26,35,68,.42)':state.time>16?'rgba(159,100,61,.16)':'rgba(255,230,158,.035)';ctx.fillRect(0,0,W,H);
 if(state.area==='dungeon'){ctx.fillStyle='rgba(15,18,23,.18)';ctx.fillRect(0,0,W,H);const g=ctx.createRadialGradient(player.x-camera.x,player.y-camera.y,20,player.x-camera.x,player.y-camera.y,155);g.addColorStop(0,'rgba(239,185,107,.10)');g.addColorStop(1,'rgba(10,14,18,.5)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
 drawMini();
}
function drawMini(){mctx.clearRect(0,0,76,64);mctx.fillStyle=state.area==='village'?'#62895a':'#5d5548';mctx.fillRect(0,0,76,64);const cfg=maps[state.area],scale=Math.min(76/(cfg.w*T),64/(cfg.h*T));for(let y=0;y<cfg.h;y++)for(let x=0;x<cfg.w;x++){const t=worldMap[y]?.[x];if(t===1){mctx.fillStyle=state.area==='village'?'#34553d':'#353b3a';mctx.fillRect(x*T*scale,y*T*scale,Math.max(1,T*scale),Math.max(1,T*scale))}if(t===4){mctx.fillStyle='#3d858c';mctx.fillRect(x*T*scale,y*T*scale,Math.max(1,T*scale),Math.max(1,T*scale))}}for(const e of entities){if(e.alive&&['boss','portal','chest'].includes(e.type)){mctx.fillStyle=e.type==='boss'?'#ed7264':'#eecb79';mctx.fillRect(e.x*scale-1,e.y*scale-1,3,3)}}mctx.fillStyle='#fff0bb';mctx.fillRect(player.x*scale-1,player.y*scale-1,4,4)}
function update(dt){if(!state.started)return;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)ui.toast.classList.remove('show')}if(state.paused)return;state.time=(state.time+dt*.04)%24;document.getElementById('clock').textContent=(state.time>6&&state.time<19?'☀ ':'☾ ')+String(Math.floor(state.time)).padStart(2,'0')+':'+String(Math.floor(state.time%1*60/10)*10).padStart(2,'0');document.getElementById('areaSub').textContent=maps[state.area].sub+' · '+(state.time>6&&state.time<18?'Gündüz':'Gece');move(dt);
 for(const e of entities){if(!e.alive)continue;if(['wolf','slime','wisp','boss'].includes(e.type)){const d=Math.hypot(player.x-e.x,player.y-e.y);if(d<115&&d>21){e.x+=(player.x-e.x)/d*(e.type==='boss'?.25:.35);e.y+=(player.y-e.y)/d*(e.type==='boss'?.25:.35)}e.attack-=dt;if(d<20&&e.attack<=0){e.attack=e.type==='boss'?1.1:1.55;if(player.shield<=0){player.hp=Math.max(0,player.hp-(e.damage||6));player.hit=.2;toast('Hasar aldın');updateHUD();if(player.hp<=0){state.paused=true;ui.shade.classList.add('show');ui.shade.querySelector('.eyebrow').textContent='YOLCULUK BURADA BİTMİYOR';ui.shade.querySelector('h2').innerHTML='DÜŞTÜN<br>KAHRAMAN';ui.shade.querySelector('p').textContent='Köy hanında uyandın. İlerlemen güvende.';ui.shade.querySelector('.menu-buttons').innerHTML='<button id="revive">↻ &nbsp; HAN’DA UYAN</button>';document.getElementById('revive').onclick=()=>{player.hp=player.maxHp;player.mp=player.maxMp;state.paused=false;loadArea('village');ui.shade.classList.remove('show')}}}}}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.x+=p.vx;p.y+=p.vy;p.life-=dt;let hit=false;for(const e of entities){if(e.alive&&['wolf','slime','wisp','boss'].includes(e.type)&&Math.hypot(e.x-p.x,e.y-p.y)<13){e.hp-=18;particles.push({x:e.x,y:e.y-4,life:.4,type:'hit'});if(e.hp<=0)kill(e);hit=true;break}}if(hit||p.life<=0)projectiles.splice(i,1)}
 for(let i=particles.length-1;i>=0;i--){particles[i].life-=dt;if(particles[i].life<=0)particles.splice(i,1)}if(Math.random()<dt*1.3){particles.push({x:camera.x+rand(0,W),y:camera.y+rand(0,H),life:2,type:'dust'})}if(state.area==='dungeon'&&Math.hypot(player.x-128,player.y-176)<12&&!state.plate){state.plate=true;state.doorOpen=true;toast('Basınç plakası etkin · taş kapı açıldı!')} }
function frame(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(frame)}
// Buttons and mobile support
window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
document.getElementById('newGame').onclick=()=>startGame(false);document.getElementById('continueGame').onclick=()=>startGame(true);document.getElementById('menuHelp').onclick=()=>dialogue('NASIL OYNANIR',['WASD ya da yön tuşlarıyla yürü. Space ile yakındaki düşmanlara kılıç savur.','Q ateş topu, Shift takla, H iksir. E ile köylülerle konuş ve nesneleri kullan.','Mira’yı bul, kuzeydeki taş kemerden zindana gir. Plakayı bul ve gölge muhafızını yen!']);document.getElementById('saveBtn').onclick=save;document.getElementById('pauseBtn').onclick=togglePause;document.getElementById('settingsBtn').onclick=()=>dialogue('AYARLAR',['Ses ve müzik: tarayıcı etkileşimi başladıktan sonra chiptune sesleri etkinleşir.','Kontroller: WASD / oklar hareket · Space saldırı · Shift takla · Q ateş topu · H iksir · E etkileşim.']);document.getElementById('closeInventory').onclick=toggleInv;
for(const el of document.querySelectorAll('.touch-btn')){const down=e=>{e.preventDefault();el.classList.add('down');if(el.dataset.key){keys[el.dataset.key.toLowerCase()]=true}else if(el.dataset.action==='attack')attack();else if(el.dataset.action==='dodge')dodge();else if(el.dataset.action==='skill')cast()};const up=e=>{e.preventDefault();el.classList.remove('down');if(el.dataset.key)keys[el.dataset.key.toLowerCase()]=false};el.addEventListener('pointerdown',down);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('pointerleave',up)}
ui.dialog.addEventListener('click',e=>{if(!e.target.closest('button'))advanceDialogue()});document.getElementById('screen').addEventListener('pointerdown',e=>{if(e.target===canvas&&state.dialogue)advanceDialogue()});
// Mobile actions: double tap right side to interact, long-press inventory on top icon
updateHUD();initVillage();requestAnimationFrame(frame);
})();
</script>
</body></html>

