function drawEntity(e){const x=e.x-camera.x,y=e.y-camera.y;if(x<-24||y<-24||x>W+24||y>H+24)return;if(['mira','smith','merchant','innkeeper','villager'].includes(e.type)){const c={mira:'#865b85',smith:'#87654a',merchant:'#d3a54e',innkeeper:'#537b85',villager:'#78915a'}[e.type];drawActor(e.x,e.y,c,'person',Math.floor(e.anim*3),e.dir);ctx.fillStyle='#fff1ce';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText(({mira:'MİRA',smith:'BORAN',merchant:'LİNA',innkeeper:'TOM',villager:'ELİ'})[e.type],x,y-19)}else if(e.type==='portal'){ctx.fillStyle='#6ee0ca';ctx.globalAlpha=.55+Math.sin(performance.now()/220)*.2;ctx.beginPath();ctx.ellipse(x,y,10,15,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#b8fff0';ctx.stroke()}else if(e.type==='exit'){ctx.fillStyle='#8cad6c';ctx.fillRect(x-9,y-6,18,12);ctx.fillStyle='#25322c';ctx.fillRect(x-5,y-4,10,8)}else if(e.type==='chest'){ctx.fillStyle=e.opened?'#655445':'#9a683b';ctx.fillRect(x-7,y-6,14,11);ctx.fillStyle='#e7c56e';ctx.fillRect(x-2,y-2,4,3)}else if(e.type==='block')drawActor(e.x,e.y,'#777','block');else if(['wolf','slime','wisp','boss'].includes(e.type)){const c={wolf:'#936b59',slime:'#65b99a',wisp:'#a6dcdb',boss:'#784f7c'}[e.type];if(e.type==='boss')drawActor(e.x,e.y,c,'boss');else{ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y-3,e.type==='wisp'?7:9,e.type==='slime'?7:6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.type==='wisp'?'#795bb2':'#312c38';ctx.fillRect(x-4,y-5,2,2);ctx.fillRect(x+2,y-5,2,2)}if(e.hp<e.maxHp){ctx.fillStyle='#281e25';ctx.fillRect(x-10,y-13,20,3);ctx.fillStyle='#e96b64';ctx.fillRect(x-10,y-13,20*Math.max(0,e.hp/e.maxHp),3)}}}
