function drawMini(){mctx.clearRect(0,0,76,64);mctx.fillStyle=state.area==='village'?'#63854d':'#5b555a';mctx.fillRect(0,0,76,64);const mw=maps[state.area].w,mh=maps[state.area].h;mctx.fillStyle='#b69a67';if(state.area==='village'){mctx.fillRect(5,31,66,3);mctx.fillRect(30,14,3,40)}else{mctx.fillStyle='#78726c';mctx.fillRect(8,10,20,42);mctx.fillRect(43,10,20,42)}mctx.fillStyle='#ffe18a';mctx.fillRect(player.x/(mw*T)*76-2,player.y/(mh*T)*64-2,4,4);if(state.area==='dungeon'&&!state.bossDown){mctx.fillStyle='#e76571';mctx.fillRect(54,34,3,3)}}
function damagePlayer(amount){if(player.shield>0)return;player.hp=Math.max(0,player.hp-Math.max(1,amount-player.def));player.hit=.2;updateHUD();if(player.hp<=0){player.hp=player.maxHp;player.mp=Math.max(0,player.mp-10);player.x=state.area==='village'?246:56;player.y=state.area==='village'?180:241;toast('Bayıldın · güvenli noktada uyandın')}}
function update(dt){if(!state.started)return;if(state.toastTimer>0&&(state.toastTimer-=dt)<=0)ui.toast.classList.remove('show');if(state.paused)return;state.time=(state.time+dt*.035)%24;document.getElementById('clock').textContent=(state.time<6||state.time>19?'☾ ':'☀ ')+String(Math.floor(state.time)).padStart(2,'0')+':'+String(Math.floor(state.time%1*60/10)*10).padStart(2,'0');document.getElementById('areaSub').textContent=maps[state.area].sub+' · '+(state.time>6&&state.time<18?'Gündüz':'Gece');move(dt);for(const e of entities){if(!e.alive)continue;e.anim+=dt;if(['wolf','slime','wisp','boss'].includes(e.type)){const d=Math.hypot(player.x-e.x,player.y-e.y);if(d<115&&d>18){const sp=(e.type==='boss'?22:29)*dt;e.x+=(player.x-e.x)/d*sp;e.y+=(player.y-e.y)/d*sp}if(d<19&&e.attack<=0){damagePlayer(e.damage||6);e.attack=e.type==='boss'?1.1:.9}e.attack=Math.max(0,e.attack-dt)}}for(const p of projectiles){p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.life-=dt;for(const e of entities)if(e.alive&&['wolf','slime','wisp','boss'].includes(e.type)&&Math.hypot(e.x-p.x,e.y-p.y)<14){e.hp-=18;p.life=0;particles.push({x:e.x,y:e.y,life:.45,type:'hit'});if(e.hp<=0)kill(e);break}}projectiles=projectiles.filter(p=>p.life>0);for(const p of particles)p.life-=dt;particles=particles.filter(p=>p.life>0);updateHUD()}
