function bindTouch(){document.querySelectorAll('.touch-btn[data-key]').forEach(b=>{const k=b.dataset.key;const on=e=>{e.preventDefault();keys[k.toLowerCase()]=true;b.classList.add('pressed')},off=e=>{e.preventDefault();keys[k.toLowerCase()]=false;b.classList.remove('pressed')};b.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave'].forEach(n=>b.addEventListener(n,off))});document.querySelectorAll('.touch-btn[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();const a=b.dataset.action;if(a==='attack')attack();else if(a==='skill')cast();else if(a==='dodge')dodge();b.classList.add('pressed');setTimeout(()=>b.classList.remove('pressed'),130)}))}
