  let pages=[];
  for(let i=0;i<50;i++){try{pages=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();if(pages.some(x=>x.type==='page'))break}catch{}await sleep(100)}
  const page=pages.find(x=>x.type==='page');if(!page)throw Error('Chromium page did not start');
  ws=new WebSocket(page.webSocketDebuggerUrl);await new Promise((resolve,reject)=>{ws.onopen=resolve;ws.onerror=reject});
  let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
  const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
  const evalJS=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.result.value;
  const key=async(k,type)=>send('Input.dispatchKeyEvent',{type,key:k,code:k===' '?'Space':k,keyCode:k===' '?' ':k.charCodeAt(0),windowsVirtualKeyCode:k===' '?' ':k.charCodeAt(0)});
  const tap=async k=>{await key(k,'keyDown');await key(k,'keyUp')};
  const dismissIntro=async()=>{await tap('e');await tap('e')};
  await sleep(350);
  const blankSave={player:{x:300,y:126,hp:100,mp:48,maxHp:100,maxMp:48,attack:12,def:3,potions:2},state:{area:'dungeon',quest:1,gold:10,xp:0,level:1,skillPoint:0,bossDown:false,crystals:0,inventoryItems:['Kıvılcım Kılıcı'],chestOpened:false,doorOpen:true,plate:true,blockMoved:true,blockX:136,blockY:184}};
  await evalJS(`localStorage.setItem('kulKristalSave',${JSON.stringify(JSON.stringify(blankSave))})`);
  await send('Page.reload',{ignoreCache:true});await sleep(500);
  await evalJS(`document.querySelector('#continueGame').click()`);await sleep(120);await dismissIntro();await sleep(100);
  await tap('e');await sleep(100);await evalJS(`document.querySelector('#saveBtn').click()`);await sleep(50);
  let first=JSON.parse(await evalJS(`localStorage.getItem('kulKristalSave')`));
  const chestLootPersisted=first.state.chestOpened===true&&first.state.gold===42&&first.player.potions===3;
