  const bossProgression=boss.state.bossDown===true&&boss.state.quest===2&&boss.state.crystals===1;
  const result={chestLootPersisted,chestDoesNotDuplicate,modalGuardsInput,bossProgression,bossState:{hp:boss.player.hp,quest:boss.state.quest,crystals:boss.state.crystals,bossDown:boss.state.bossDown}};
