  ws.close();chrome.kill();if(!chestLootPersisted||!chestDoesNotDuplicate||!modalGuardsInput||!bossProgression)process.exitCode=1;
 }catch(e){if(ws)ws.close();chrome.kill();console.error(e);process.exitCode=1}
})();

